import{_ as n,o,c as e,a2 as c}from"./chunks/framework.O93z6AWZ.js";const m=JSON.parse('{"title":"Nộp Bài Đồ Án","description":"","frontmatter":{"title":"Nộp Bài Đồ Án"},"headers":[],"relativePath":"nop_bai.md","filePath":"nop_bai.md"}'),i={name:"nop_bai.md"};function h(a,t,r,s,g,l){return o(),e("div",null,[...t[0]||(t[0]=[c('<h1 id="📤-nop-bai-đo-an-len-repo-chung-cua-lop" tabindex="-1">📤 Nộp Bài Đồ Án Lên Repo Chung Của Lớp <a class="header-anchor" href="#📤-nop-bai-đo-an-len-repo-chung-cua-lop" aria-label="Permalink to &quot;📤 Nộp Bài Đồ Án Lên Repo Chung Của Lớp&quot;">​</a></h1><blockquote><p>Sau khi hoàn thành đồ án theo đề tài đã chọn (xem <a href="/hmyt-book/du_an_mon_hoc">Khung Quản Lý &amp; Rubric</a>), mỗi nhóm nộp bài bằng cách mở <strong>Pull Request</strong> vào repo chung của lớp:</p><h2 id="👉-github-com-fossbk-spec-hmyt-project" tabindex="-1">👉 <a href="https://github.com/fossbk-spec/hmyt-project" target="_blank" rel="noreferrer">github.com/fossbk-spec/hmyt-project</a> <a class="header-anchor" href="#👉-github-com-fossbk-spec-hmyt-project" aria-label="Permalink to &quot;👉 [github.com/fossbk-spec/hmyt-project](https://github.com/fossbk-spec/hmyt-project)&quot;">​</a></h2></blockquote><p>Trang này chỉ tóm tắt quy trình — hướng dẫn đầy đủ, chính xác nhất luôn nằm trong <code>CONTRIBUTING.md</code> của repo trên (đọc bản đó trước khi nộp, trang này có thể chưa cập nhật kịp nếu quy trình đổi).</p><hr><h2 id="_1-vi-sao-nop-qua-pull-request-khong-phai-email-drive" tabindex="-1">1. Vì sao nộp qua Pull Request, không phải email/Drive? <a class="header-anchor" href="#_1-vi-sao-nop-qua-pull-request-khong-phai-email-drive" aria-label="Permalink to &quot;1. Vì sao nộp qua Pull Request, không phải email/Drive?&quot;">​</a></h2><ul><li><strong>Không nhóm nào ghi đè bài nhóm khác</strong> — mỗi nhóm chỉ được sửa đúng 1 thư mục của mình, CI tự động chặn nếu PR đụng sang thư mục khác.</li><li><strong>Có lịch sử rõ ràng</strong> — mọi lần nộp/sửa đều là 1 commit, không lo mất bài hay nộp nhầm bản cũ.</li><li><strong>Tự động kiểm tra trước khi giảng viên xem</strong> — thiếu file, còn để giá trị mẫu, lỡ tay commit khóa API... đều bị chặn ngay ở bước CI.</li></ul><h2 id="_2-5-buoc-nop-bai" tabindex="-1">2. 5 bước nộp bài <a class="header-anchor" href="#_2-5-buoc-nop-bai" aria-label="Permalink to &quot;2. 5 bước nộp bài&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Bước</th><th>Việc cần làm</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>1</strong></td><td><strong>Fork</strong> repo <a href="https://github.com/fossbk-spec/hmyt-project" target="_blank" rel="noreferrer"><code>hmyt-project</code></a> về tài khoản GitHub của nhóm</td></tr><tr><td style="text-align:center;"><strong>2</strong></td><td>Tạo branch <code>submit/&lt;topic_slug&gt;-&lt;ma_nhom&gt;</code>, copy thư mục <code>submissions/_TEMPLATE/</code> thành <code>submissions/&lt;topic_slug&gt;_&lt;ma_nhom&gt;/</code></td></tr><tr><td style="text-align:center;"><strong>3</strong></td><td>Điền <code>submission.json</code> (mã đề tài, mã nhóm, MSSV) + báo cáo (<code>report/</code>) + mã nguồn (<code>src/</code>)</td></tr><tr><td style="text-align:center;"><strong>4</strong></td><td>Chạy kiểm tra cục bộ: <code>python scripts/validate_submission.py submissions/&lt;topic_slug&gt;_&lt;ma_nhom&gt;</code> — phải thấy <code>[PASSED]</code></td></tr><tr><td style="text-align:center;"><strong>5</strong></td><td>Push lên fork, mở <strong>Pull Request</strong> vào <code>main</code> của <code>hmyt-project</code>, chờ CI xanh ✅ rồi chờ giảng viên/TA duyệt</td></tr></tbody></table><p><code>topic_slug</code> là tên đề tài đúng như trong URL trang đề tài của bạn, vd đề tài <a href="/hmyt-book/du_an/suy_tim_risk_dxai">3.4 Suy tim cấp tốc</a> → slug là <code>suy_tim_risk_dxai</code>.</p><h2 id="_3-quy-tac-bat-buoc-ci-se-chan-pr-neu-vi-pham" tabindex="-1">3. Quy tắc bắt buộc (CI sẽ chặn PR nếu vi phạm) <a class="header-anchor" href="#_3-quy-tac-bat-buoc-ci-se-chan-pr-neu-vi-pham" aria-label="Permalink to &quot;3. Quy tắc bắt buộc (CI sẽ chặn PR nếu vi phạm)&quot;">​</a></h2><ol><li><strong>Không dữ liệu bệnh nhân thật</strong> — chỉ dùng dữ liệu công khai (MIMIC/PTB-XL/PhysioNet/UCI...) hoặc dữ liệu tự mô phỏng, đúng nguyên tắc xuyên suốt của <a href="/hmyt-book/du_an_mon_hoc">Khung Quản Lý &amp; Rubric</a>.</li><li><strong>Không commit khóa API/token/mật khẩu/file <code>.env</code>.</strong></li><li><strong>Dùng MSSV, không dùng họ tên đầy đủ</strong> trong <code>submission.json</code> hay bất kỳ file nào — repo này công khai vĩnh viễn trên GitHub.</li><li><strong>File dữ liệu lớn (&gt;10MB)</strong> để trên Google Drive/Kaggle/HuggingFace, chỉ dán link vào <code>README.md</code> của bài nộp.</li><li><strong>1 Pull Request = 1 thư mục</strong> — không gộp nhiều lần sửa của nhiều nhóm vào cùng 1 PR.</li></ol><h2 id="_4-cau-hoi-thuong-gap" tabindex="-1">4. Câu hỏi thường gặp <a class="header-anchor" href="#_4-cau-hoi-thuong-gap" aria-label="Permalink to &quot;4. Câu hỏi thường gặp&quot;">​</a></h2><p><strong>Nhóm mình có thể chọn cùng đề tài với nhóm khác không?</strong> Có — mỗi nhóm có thư mục riêng theo mã nhóm, không xung đột.</p><p><strong>Nộp rồi có sửa lại được không?</strong> Trước khi merge: push thêm commit lên cùng branch, PR tự cập nhật. Sau khi merge: liên hệ trực tiếp giảng viên, không tự sửa qua PR thường (branch <code>main</code> được bảo vệ để giữ toàn vẹn lịch sử nộp bài).</p><p><strong>CI báo FAIL, xem lỗi ở đâu?</strong> Mở tab &quot;Checks&quot; trên Pull Request — log liệt kê chính xác dòng/file vi phạm bằng tiếng Việt.</p><div class="tip custom-block"><p class="custom-block-title">Đọc thêm</p><p>Toàn bộ chi tiết, ví dụ, và giải đáp mở rộng nằm trong <a href="https://github.com/fossbk-spec/hmyt-project/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer"><code>CONTRIBUTING.md</code></a> của repo <code>hmyt-project</code>.</p></div>',16)])])}const p=n(i,[["render",h]]);export{m as __pageData,p as default};
